package org.apache.commons.lang3.text.translate;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class NumericEntityUnescaper_ESTest_test2 extends NumericEntityUnescaper_ESTest_scaffolding {

    /**
     * With no OPTION supplied, the unescaper defaults to semiColonRequired.
     * The input ends with the numeric entity "&#3" but has no trailing
     * semicolon, so it is left untranslated and the string is returned
     * unchanged (the four leading NUL characters followed by "&#3").
     */
    @Test(timeout = 4000)
    public void translateNumericEntityWithoutSemicolonLeavesInputUnchanged() throws Throwable {
        NumericEntityUnescaper.OPTION[] noOptions = new NumericEntityUnescaper.OPTION[0];
        NumericEntityUnescaper unescaper = new NumericEntityUnescaper(noOptions);

        // Four unset (NUL) chars followed by the semicolon-less entity "&#3".
        char[] inputChars = new char[7];
        inputChars[4] = '&';
        inputChars[5] = '#';
        inputChars[6] = '3';
        CharBuffer input = CharBuffer.wrap(inputChars);

        String result = unescaper.translate((CharSequence) input);

        assertEquals("����&#3", result);
    }
}
